import React from "react";
import Movie from "./Movie";

function Movies(props) {
  console.log("Movies props:", props); // Для отладки

  const { movies = [] } = props;

  return (
    <div className="row">
      {movies.length ? (
        movies.map((movie) => (
          <div className="col s12 m6 l4" key={movie.imdbID}>
            <Movie {...movie} />
          </div>
        ))
      ) : (
        <div className="center-align" style={{ marginTop: "50px" }}>
          <img
            src="https://cdn-icons-png.flaticon.com/512/7486/7486791.png"
            alt="Not found"
            width="150"
            style={{ opacity: 0.5 }}
          />
          <h5 style={{ color: "#777" }}>Ничего не найдено</h5>
          <p>Попробуйте изменить поисковый запрос</p>
        </div>
      )}
    </div>
  );
}

export default Movies;
